const MISCONCEPTIONS: { misconception: string; correction: string }[] = [
  {
    misconception: 'If P(heads) = 1/2, heads and tails must ALTERNATE.',
    correction:
      'Independence means every toss ignores history: HHHH is exactly as likely as HTHT (1/16 each). The 1/2 promise is about the LONG-RUN proportion, not a rhythm. Roll 50 in the Dice Lab — streaks are everywhere.',
  },
  {
    misconception: 'Four sixes in a row means a six is "due" (or "unlikely") next.',
    correction:
      'The gambler fallacy. A fair die has no memory: P(6) = 1/6 on every single throw, whatever happened before. Long-run averages emerge from millions of memoryless throws — not from cosmic balancing.',
  },
  {
    misconception: 'With many trials the empirical value will exactly EQUAL the theoretical.',
    correction:
      'It converges toward, not arrives at: the gap shrinks roughly like 1/√N. At 10 000 trials a gap of ~0.01 is still normal. Equality after finitely many trials would itself be a coincidence.',
  },
  {
    misconception: 'A probability of 0.99 means it will definitely happen.',
    correction:
      '0.99 means it fails once in every hundred, on average — and "average" events DO occur. Only P = 1 (with all outcomes listed) means certainty, and even then only within the model.',
  },
  {
    misconception: 'Empirical and theoretical probability are two names for the same thing.',
    correction:
      'Theoretical comes from REASONING about equally likely cases (6 faces → 1/6). Empirical comes from COUNTING actual runs (28 sixes in 200 throws = 0.14). They answer different questions and only agree in the long run — the two panels of this sim never merge.',
  },
];

// ─── deterministic RNG (seeded LCG, no render-time randomness) ───

function makeLcg(seed: number) {
  let s = seed % 2147483647;
  if (s <= 0) s += 2147483646;
  return () => {
    s = (s * 16807) % 2147483647;
    return (s - 1) / 2147483646;
  };
}

interface Trial {
  mode: Mode;
  a: number;
  b: number; // second die (twodice) or coin pair flag
}

function rollOne(r: number): number {
  return 1 + Math.floor(r * 6);
}

function eventHolds(mode: Mode, ev: string, t: Trial): boolean {
  if (mode === 'die') {
    if (ev === 'six') return t.a === 6;
    if (ev === 'even') return t.a % 2 === 0;
    if (ev === 'prime') return t.a === 2 || t.a === 3 || t.a === 5;
    if (ev === 'gt4') return t.a > 4;
  }
  if (mode === 'twodice') {
    const s = t.a + t.b;
    if (ev === 'sum7') return s === 7;
    if (ev === 'sum2') return s === 2;
    if (ev === 'doubles') return t.a === t.b;
    if (ev === 'sumGTE10') return s >= 10;
  }
  if (mode === 'coin') {
    if (ev === 'heads') return t.a === 1;
    if (ev === 'hh') return t.a === 1 && t.b === 1;
  }
  return false;
}

// ─── main component ───

export function C9_MathsProbabilitySim() {
  const [tab, setTab] = useState<TabKey>('predict');

  const [mode, setMode] = useState<Mode>('die');
  const [eventId, setEventId] = useState('six');
  const [trials, setTrials] = useState<Trial[]>([]);
  const [seed, setSeed] = useState(42);
  const [lastFace, setLastFace] = useState<Trial | null>(null);

  const [predicted, setPredicted] = useState<number | null>(null);
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [revealed, setRevealed] = useState<Record<string, boolean>>({});
  const [hintLevel, setHintLevel] = useState<Record<string, number>>({});
  const [tierFilter, setTierFilter] = useState<'all' | Challenge['tier']>('all');
  const [openMisc, setOpenMisc] = useState<number | null>(null);

  const events = EVENTS[mode];
  const activeEvent = events.find((e) => e.id === eventId) ?? events[0];
  const N = trials.length;
  const hits = useMemo(() => trials.filter((t) => eventHolds(mode, activeEvent.id, t)).length, [trials, mode, activeEvent.id]);
  const empirical = N > 0 ? hits / N : NaN;
  const theoretical = activeEvent.theo;
  const gap = N > 0 ? Math.abs(empirical - theoretical) : NaN;
  const envelope = N > 0 ? 1 / Math.sqrt(N) : NaN;

  const addTrials = (k: number) => {
    const rng = makeLcg(seed * 7919 + N * 104729 + 13);
    const batch: Trial[] = [];
    for (let i = 0; i < k; i++) {
      const a = mode === 'coin' ? (rng() < 0.5 ? 1 : 0) : rollOne(rng());
      const b = mode === 'twodice' ? rollOne(rng()) : mode === 'coin' ? (rng() < 0.5 ? 1 : 0) : 0;
      batch.push({ mode, a, b });
    }
    setLastFace(batch[k - 1] ?? null);
    setTrials((t) => [...t, ...batch].slice(-50000));
  };

  // per-face tally for the die mode chart
  const faceCounts = useMemo(() => {
    const counts = [0, 0, 0, 0, 0, 0];
    trials.forEach((t) => {
      if (mode === 'die') counts[t.a - 1] += 1;
      else if (mode === 'twodice') {
        const s = t.a + t.b;
        if (s >= 2 && s <= 12) counts[s - 2] += 1;
      } else {
        counts[t.a] += 1; // 0 heads-bucket, 1 heads-bucket
      }
    });
    return counts;
  }, [trials, mode]);

  // per-sum tally for two dice (2..12)
  const sumCounts = useMemo(() => {
    const counts: number[] = Array(11).fill(0);
    trials.forEach((t) => {
      if (mode === 'twodice') {
        const s = t.a + t.b;
        counts[s - 2] += 1;
      }
    });
    return counts;
  }, [trials, mode]);

  // trend series (running empirical probability, sampled)
  const trendSeries = useMemo(() => {
    const pts: { n: number; p: number }[] = [];
    let hitCount = 0;
    const step = Math.max(1, Math.floor(trials.length / 200));
    for (let i = 0; i < trials.length; i++) {
      if (eventHolds(mode, activeEvent.id, trials[i])) hitCount += 1;
      if ((i + 1) % step === 0 || i === trials.length - 1) {
        pts.push({ n: i + 1, p: hitCount / (i + 1) });
      }
    }
    return pts;
  }, [trials, mode, activeEvent.id]);

  const changeMode = (m: Mode) => {
    setMode(m);
    setEventId(EVENTS[m][0].id);
    setTrials([]);
    setLastFace(null);
  };

  const score = useMemo(() => {
    let right = 0;
    let attempted = 0;
    Object.entries(answers).forEach(([id, choice]) => {
      const ch = CHALLENGES.find((q) => q.id === id);
      if (ch) {
        attempted += 1;
        if (choice === ch.correctIndex) right += 1;
      }
    });
    return { right, attempted };
  }, [answers]);

  const visibleChallenges = CHALLENGES.filter((q) => tierFilter === 'all' || q.tier === tierFilter);

  const pickAnswer = (id: string, idx: number) => {
    if (revealed[id]) return;
    setAnswers((p) => ({ ...p, [id]: idx }));
    setRevealed((p) => ({ ...p, [id]: true }));
  };

  const resetAll = () => {
    setTrials([]);
    setSeed(42);
    setLastFace(null);
    setMode('die');
    setEventId('six');
    setPredicted(null);
  };

  const W = 620;
  const H = 260;
  // chart for die faces / sums / coin
  const buckets: { label: string; count: number; theo: number }[] =
    mode === 'die'
      ? [1, 2, 3, 4, 5, 6].map((f) => ({ label: `${f}`, count: faceCounts[f - 1], theo: 1 / 6 }))
      : mode === 'twodice'
        ? Array.from({ length: 11 }, (_, i) => ({
            label: `${i + 2}`,
            count: sumCounts[i],
            theo: (6 - Math.abs(i + 2 - 7)) / 36, // ways to make the sum, out of 36
          }))
        : [{ label: 'tails', count: faceCounts[0], theo: 0.5 }, { label: 'heads', count: faceCounts[1], theo: 0.5 }];
  const maxCount = Math.max(1, ...buckets.map((b) => b.count));
  const maxRel = Math.max(0.2, ...buckets.map((b) => (N > 0 ? b.count / N : 0)), ...buckets.map((b) => b.theo));

  return (
    <div className="w-full max-w-5xl mx-auto p-4 md:p-6 bg-slate-950 rounded-3xl border border-slate-800 font-sans text-slate-100 shadow-2xl">
      {/* header */}
      <div className="flex flex-wrap items-center gap-3 pb-3 mb-3 border-b border-slate-800">
        <span className="text-3xl p-2 bg-emerald-950/80 rounded-2xl border border-emerald-700">🎲</span>
        <div className="flex-1 min-w-[220px]">
          <p className="text-xs font-bold uppercase tracking-wider text-emerald-400">Class 9 Maths — Probability (Experimental Approach)</p>
          <h1 className="text-xl md:text-2xl font-black text-emerald-300">Count, Don&apos;t Guess: empirical meets theoretical</h1>
        </div>
        <div className="text-right">
          <span className="font-mono text-xs text-slate-400 block">P(E) = favourable / total</span>
          <span className="font-mono text-xs text-slate-500 block">empirical → theoretical as N → ∞</span>
        </div>
        <button onClick={resetAll} className="min-h-11 px-4 rounded-xl bg-slate-800 hover:bg-slate-700 text-sm font-bold transition-all">
          Reset
        </button>
      </div>

      {/* tab bar */}
      <nav className="flex flex-wrap gap-1.5 mb-4">
        {TABS.map((t) => (
          <button
            key={t.id}
            onClick={() => setTab(t.id)}
            className={`min-h-9 px-3 py-1.5 rounded-xl text-xs font-bold transition-all border ${
              tab === t.id
                ? 'bg-emerald-600 border-emerald-500 text-white shadow-lg shadow-emerald-900/40'
                : 'bg-slate-900 border-slate-800 text-slate-400 hover:text-slate-200 hover:border-slate-600'
            }`}
          >
            <span className="mr-1">{t.emoji}</span>
            {t.label}
          </button>
        ))}
      </nav>

      {/* shared banner */}
      <div className="p-3 mb-4 bg-slate-900/80 rounded-2xl border border-slate-800 flex flex-wrap items-center gap-x-6 gap-y-1">
        <span className="text-xs text-slate-400">experiment:</span>
        {(['die', 'twodice', 'coin'] as Mode[]).map((m) => (
          <button key={m} onClick={() => changeMode(m)}
            className={`min-h-9 px-3 py-1 rounded-lg text-xs font-bold border transition-all ${
              mode === m ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-400'
            }`}>
            {m === 'die' ? 'one die' : m === 'twodice' ? 'two dice' : 'coin pairs'}
          </button>
        ))}
        <span className="ml-auto font-mono text-xs text-emerald-300">{activeEvent.label}</span>
      </div>

      {/* ============================================================ */}
      {/* TAB 1: PREDICT                                               */}
      {/* ============================================================ */}
      {tab === 'predict' && (
        <div className="space-y-4">
          <div className="p-5 bg-slate-900/70 rounded-2xl border border-emerald-900/60">
            <p className="text-[11px] font-bold uppercase tracking-wider text-emerald-400 mb-2">Predict before you play</p>
            <p className="text-sm text-slate-200 leading-relaxed">
              You will throw ONE fair die 10 times. Roughly how many sixes do you EXPECT, and can
              the actual count ever be different?
            </p>
            <div className="mt-3 space-y-2">
              {[
                'Exactly 1 or 2 — probability forces the count',
                'About 1–2 expected, but ANY count from 0 to 10 is possible',
                'Exactly 0 — sixes are rare in short runs',
                'Exactly 5 — half of everything is sixes',
              ].map((opt, i) => {
                const chosen = predicted === i;
                const isCorrect = i === 1;
                let cls = 'border-slate-700 bg-slate-900 hover:border-emerald-600';
                if (predicted !== null && isCorrect) cls = 'border-emerald-600 bg-emerald-950/40';
                else if (chosen && !isCorrect) cls = 'border-rose-600 bg-rose-950/40';
                return (
                  <button
                    key={i}
                    onClick={() => setPredicted(i)}
                    disabled={predicted !== null}
                    className={`w-full text-left px-4 py-2.5 rounded-xl border text-sm transition-all disabled:cursor-default ${cls}`}
                  >
                    <span className="font-mono text-xs text-slate-500 mr-2">{'ABCD'[i]}</span>
                    {opt}
                    {predicted !== null && isCorrect && <span className="ml-2 text-emerald-400 font-bold text-xs">✓</span>}
                  </button>
                );
              })}
            </div>
            {predicted !== null && (
              <div className="mt-3 p-3 rounded-xl bg-amber-950/40 border border-amber-800 text-xs text-amber-200 leading-relaxed">
                P(6) = 1/6 ⇒ expect about 10/6 ≈ 1.7 sixes — but randomness lets 0 or even 5 happen.
                Press +10 in the Dice Lab a few times: short runs wander, the theory line waits.
                <button onClick={() => setTab('dice')} className="ml-2 underline font-bold text-amber-300">Open Dice Lab →</button>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            {[
              { t: 'Walk 1: ten at a time', d: 'Press +10 several times WITHOUT resetting. Watch N climb and the empirical value wobble smaller and smaller around the green theory line.' },
              { t: 'Walk 2: the fashionable sum', d: 'Switch to two dice and P(sum = 7) — the tallest bar in the 2…12 chart. The theory bars form a triangle: 1,2,3,4,5,6,5,…' },
              { t: 'Walk 3: shrink the gap', d: 'Trend Lab: the rose envelope is 1/√N. At N = 100 it is 0.1 wide; at N = 10 000 it has squeezed to 0.01. That is the whole law of large numbers.' },
            ].map((s, i) => (
              <div key={i} className="p-4 bg-slate-900/70 rounded-2xl border border-slate-800">
                <p className="text-xs font-bold text-slate-200 mb-1">
                  <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-emerald-600 text-[10px] font-black mr-1.5">{i + 1}</span>
                  {s.t}
                </p>
                <p className="text-xs text-slate-400 leading-relaxed">{s.d}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ============================================================ */}
      {/* TAB 2: DICE LAB                                              */}
      {/* ============================================================ */}
      {tab === 'dice' && (
        <div className="space-y-4">
          <div className="flex flex-wrap gap-2 items-center">
            {events.map((e) => (
              <button key={e.id} onClick={() => setEventId(e.id)}
                className={`min-h-11 px-3 py-2 rounded-xl text-xs font-bold border transition-all ${
                  eventId === e.id ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-600'
                }`}>
                {e.label}
              </button>
            ))}
          </div>

          <div className="flex flex-wrap gap-2 items-center">
            <button onClick={() => addTrials(1)} className="min-h-11 px-4 py-2 rounded-xl bg-slate-800 border border-slate-700 text-sm font-bold hover:bg-slate-700 transition-all">+1 throw</button>
            <button onClick={() => addTrials(10)} className="min-h-11 px-4 py-2 rounded-xl bg-slate-800 border border-slate-700 text-sm font-bold hover:bg-slate-700 transition-all">+10</button>
            <button onClick={() => addTrials(100)} className="min-h-11 px-4 py-2 rounded-xl bg-slate-800 border border-slate-700 text-sm font-bold hover:bg-slate-700 transition-all">+100</button>
            <button onClick={() => addTrials(1000)} className="min-h-11 px-4 py-2 rounded-xl bg-emerald-700 border border-emerald-600 text-sm font-bold hover:bg-emerald-600 transition-all">+1000</button>
            <button onClick={() => setTrials([])} className="min-h-11 px-4 py-2 rounded-xl bg-rose-950 border border-rose-800 text-xs font-bold text-rose-300 hover:bg-rose-900 transition-all">clear tally</button>
            <label className="text-xs text-slate-400 flex items-center gap-2 min-h-11">
              seed
              <input type="range" min={1} max={99} step={1} value={seed} aria-label="seed"
                onChange={(e) => { setSeed(Number(e.target.value)); setTrials([]); setLastFace(null); }}
                className="w-24 min-h-11 accent-emerald-500" />
              <span className="font-mono text-emerald-300">{seed}</span>
            </label>
          </div>

          {/* last throw */}
          <div className="p-3 bg-slate-900/80 rounded-2xl border border-slate-800 flex items-center gap-4">
            <span className="text-xs text-slate-400">last throw:</span>
            {lastFace === null ? (
              <span className="text-xs text-slate-500">nothing yet — press +1</span>
            ) : mode === 'coin' ? (
              <span className="font-mono text-lg font-bold text-emerald-300">{lastFace.a === 1 ? 'HEADS' : 'tails'}{mode === 'coin' ? ` + ${lastFace.b === 1 ? 'HEADS' : 'tails'}` : ''}</span>
            ) : mode === 'twodice' ? (
              <span className="font-mono text-lg font-bold text-emerald-300">{lastFace.a} + {lastFace.b} = {lastFace.a + lastFace.b}</span>
            ) : (
              <span className="font-mono text-lg font-bold text-emerald-300">die face {lastFace.a}</span>
            )}
            <span className="ml-auto font-mono text-xs text-slate-500">seeded LCG · deterministic replay</span>
          </div>

          {/* live readouts */}
          <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
            {[
              { k: 'trials N', v: `${N}` },
              { k: `${activeEvent.label} — hits`, v: `${hits}` },
              { k: 'empirical P', v: N > 0 ? empirical.toFixed(4) : '—' },
              { k: 'theoretical P', v: theoretical.toFixed(4) },
              { k: '|gap| vs 1/√N', v: N > 0 ? `${gap.toFixed(4)} vs ${envelope.toFixed(4)}` : '—' },
            ].map((x) => (
              <div key={x.k} className="p-2.5 bg-slate-900/80 rounded-xl border border-slate-800">
                <p className="text-[10px] uppercase tracking-wider text-slate-500 font-bold">{x.k}</p>
                <p className="font-mono text-sm font-bold text-emerald-300">{x.v}</p>
              </div>
            ))}
          </div>

          {/* frequency chart */}
          <div className="bg-slate-900 rounded-2xl border border-slate-800 p-3">
            <p className="text-[11px] font-bold uppercase tracking-wider text-slate-400 mb-2">relative frequency per bucket vs theoretical line</p>
            <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-56 md:h-64" preserveAspectRatio="xMidYMid meet">
              {(() => {
                const bw = (W - 60) / buckets.length;
                return (
                  <g>
                    {/* theory line */}
                    <line x1={30} y1={H - 30 - (maxRel > 0 ? theoretical / maxRel : 0) * (H - 60)} x2={W - 20} y2={H - 30 - (theoretical / maxRel) * (H - 60)} stroke="#34d399" strokeWidth={1.5} strokeDasharray="6 4" />
                    <text x={W - 120} y={H - 36 - (theoretical / maxRel) * (H - 60)} fontSize={10} fill="#34d399" fontFamily="monospace">theory {theoretical.toFixed(3)}</text>
                    {buckets.map((b, i) => {
                      const rel = N > 0 ? b.count / N : 0;
                      const hgt = (rel / maxRel) * (H - 60);
                      return (
                        <g key={i}>
                          <rect x={30 + i * bw + bw * 0.15} y={H - 30 - hgt} width={bw * 0.7} height={Math.max(0.5, hgt)}
                            fill={Math.abs(rel - b.theo) < 0.02 ? '#34d399' : '#0f766e'} opacity={0.85}
                            style={{ transition: 'all 150ms ease-out' }} />
                          <text x={30 + i * bw + bw / 2} y={H - 14} fontSize={11} fill="#64748b" textAnchor="middle" fontFamily="monospace">{b.label}</text>
                          <text x={30 + i * bw + bw / 2} y={H - 34 - hgt} fontSize={10} fill="#94a3b8" textAnchor="middle" fontFamily="monospace">
                            {N > 0 ? `${rel.toFixed(3)}` : ''}
                          </text>
                        </g>
                      );
                    })}
                  </g>
                );
              })()}
            </svg>
          </div>

          <div className="p-4 bg-slate-900/70 rounded-2xl border border-amber-900/50">
            <p className="text-[11px] font-bold uppercase tracking-wider text-amber-400 mb-2">What to try</p>
            <p className="text-xs text-slate-300 leading-relaxed">
              ① With one die and P(getting a 6): press +10 five times. The empirical value lurches
              (0.000, 0.100, 0.033…) — sometimes ZERO sixes in 30 throws, which is perfectly normal
              for 1/6 events. Then hit +1000 twice and watch it pin toward 0.1667.
            </p>
            <p className="text-xs text-slate-300 leading-relaxed mt-1.5">
              ② Switch to two dice, P(sum = 2). Its theory is 1/36 ≈ 0.028 — you need hundreds of
              throws before the empirical bar is even visible. Rare events demand big samples: that
              is why surveys report sample sizes.
            </p>
          </div>
        </div>
      )}

      {/* ============================================================ */}
      {/* TAB 3: TREND LAB                                             */}
      {/* ============================================================ */}
      {tab === 'trend' && (
        <div className="space-y-4">
          <p className="text-xs text-slate-400 leading-relaxed">
            The running empirical probability after every recorded throw, against the theoretical
            value and the 1/√N noise envelope. Needs trials — generate them here:
            <button onClick={() => addTrials(100)} className="mx-2 min-h-9 px-3 rounded-lg bg-slate-800 border border-slate-700 text-xs font-bold hover:bg-slate-700 transition-all">+100</button>
            <button onClick={() => addTrials(1000)} className="min-h-9 px-3 rounded-lg bg-emerald-700 border border-emerald-600 text-xs font-bold hover:bg-emerald-600 transition-all">+1000</button>
          </p>

          <div className="bg-slate-900 rounded-2xl border border-slate-800 p-3">
            <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-56 md:h-72" preserveAspectRatio="xMidYMid meet">
              {(() => {
                if (trendSeries.length < 2) {
                  return (
                    <text x={W / 2} y={H / 2} fontSize={13} fill="#64748b" textAnchor="middle">
                      roll some dice first (Dice Lab or the buttons above)
                    </text>
                  );
                }
                const nMax = trendSeries[trendSeries.length - 1].n;
                const xOf = (n: number) => 40 + (n / nMax) * (W - 60);
                // y scale: theoretical ± 3.5/sqrt(Nmin)... use fixed band around theory
                const spread = Math.max(0.12, Math.min(0.5, 3.5 / Math.sqrt(nMax)) + 0.02);
                const yTop = theoretical + spread;
                const yBot = Math.max(0, theoretical - spread);
                const yOf = (p: number) => H - 25 - ((p - yBot) / (yTop - yBot)) * (H - 50);
                const envPts = [nMax * 0.02, nMax * 0.1, nMax * 0.25, nMax * 0.5, nMax].map((n) => ({
                  n, up: theoretical + 1 / Math.sqrt(n), dn: theoretical - 1 / Math.sqrt(n),
                }));
                return (
                  <g>
                    {/* theoretical line */}
                    <line x1={40} y1={yOf(theoretical)} x2={W - 20} y2={yOf(theoretical)} stroke="#34d399" strokeWidth={2} />
                    <text x={W - 180} y={yOf(theoretical) - 6} fontSize={11} fill="#34d399" fontFamily="monospace">theoretical {theoretical.toFixed(3)}</text>
                    {/* envelope */}
                    <polyline fill="none" stroke="#fb7185" strokeWidth={1.2} strokeDasharray="5 4"
                      points={envPts.map((p) => `${xOf(p.n)},${yOf(Math.min(yTop, p.up))}`).join(' ')} />
                    <polyline fill="none" stroke="#fb7185" strokeWidth={1.2} strokeDasharray="5 4"
                      points={envPts.map((p) => `${xOf(p.n)},${yOf(Math.max(yBot, p.dn))}`).join(' ')} />
                    <text x={W - 180} y={yOf(Math.min(yTop, theoretical + 1 / Math.sqrt(nMax * 0.02)))} fontSize={10} fill="#fb7185" fontFamily="monospace">±1/√N envelope</text>
                    {/* running empirical */}
                    <polyline fill="none" stroke="#38bdf8" strokeWidth={1.8}
                      points={trendSeries.map((p) => `${xOf(p.n)},${yOf(p.p)}`).join(' ')} />
                    {/* x labels */}
                    {[0.02, 0.25, 0.5, 1].map((f) => (
                      <text key={f} x={xOf(nMax * f)} y={H - 8} fontSize={10} fill="#475569" textAnchor="middle" fontFamily="monospace">
                        N={Math.round(nMax * f)}
                      </text>
                    ))}
                  </g>
                );
              })()}
            </svg>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
            {[
              { k: 'N (trials so far)', v: `${N}` },
              { k: 'current empirical', v: N > 0 ? empirical.toFixed(4) : '—' },
              { k: 'noise width 1/√N', v: N > 0 ? envelope.toFixed(4) : '—' },
              { k: 'gap as % of envelope', v: N > 0 ? `${((gap / envelope) * 100).toFixed(0)} %` : '—' },
            ].map((x) => (
              <div key={x.k} className="p-2.5 bg-slate-900/80 rounded-xl border border-slate-800">
                <p className="text-[10px] uppercase tracking-wider text-slate-500 font-bold">{x.k}</p>
                <p className="font-mono text-sm font-bold text-emerald-300">{x.v}</p>
              </div>
            ))}
          </div>

          <div className="p-4 bg-slate-900/70 rounded-2xl border border-amber-900/50">
            <p className="text-[11px] font-bold uppercase tracking-wider text-amber-400 mb-2">What to try</p>
            <p className="text-xs text-slate-300 leading-relaxed">
              ① Build 2000 throws, then press &quot;clear tally&quot; and re-roll with the SAME
              seed: identical blue curve — this lab is deterministic, so classroom comparisons are
              fair. Change the seed slider and the run changes character entirely.
            </p>
            <p className="text-xs text-slate-300 leading-relaxed mt-1.5">
              ② Watch the gap-as-%-of-envelope readout while pressing +1000: it hovers around
              30–80 %, never collapsing to 0 — convergence is a squeeze, not a landing.
            </p>
          </div>
        </div>
      )}

      {/* ============================================================ */}
      {/* TAB 4: CHALLENGE                                             */}
      {/* ============================================================ */}
      {tab === 'challenge' && (
        <div className="space-y-3">
          <div className="flex flex-wrap items-center gap-2">
            {(['all', 'foundation', 'standard', 'advanced'] as const).map((t) => (
              <button key={t} onClick={() => setTierFilter(t)}
                className={`min-h-9 px-3 py-1.5 rounded-xl text-xs font-bold border transition-all capitalize ${
                  tierFilter === t ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-400'
                }`}>
                {t}
              </button>
            ))}
            <span className="ml-auto font-mono text-xs text-slate-400">score {score.right}/{score.attempted}</span>
          </div>

          {visibleChallenges.map((ch) => {
            const picked = answers[ch.id];
            const done = revealed[ch.id];
            const lvl = hintLevel[ch.id] ?? 0;
            return (
              <div key={ch.id} className="p-4 bg-slate-900/70 rounded-2xl border border-slate-800">
                <div className="flex flex-wrap items-center gap-2 mb-2">
                  <span className={`text-[10px] font-black px-2 py-0.5 rounded-full uppercase ${
                    ch.tier === 'foundation' ? 'bg-emerald-950 text-emerald-300' : ch.tier === 'standard' ? 'bg-amber-950 text-amber-300' : 'bg-rose-950 text-rose-300'
                  }`}>{ch.tier}</span>
                  <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{ch.skill}</span>
                </div>
                <p className="text-sm text-slate-200 font-medium mb-3">{ch.question}</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                  {ch.options.map((opt, i) => {
                    const isCorrect = i === ch.correctIndex;
                    let cls = 'border-slate-700 bg-slate-900 hover:border-emerald-600';
                    if (done && isCorrect) cls = 'border-emerald-600 bg-emerald-950/40';
                    else if (done && picked === i) cls = 'border-rose-600 bg-rose-950/40';
                    return (
                      <button key={i} onClick={() => pickAnswer(ch.id, i)} disabled={done}
                        className={`text-left px-3 py-2.5 rounded-xl border text-xs transition-all disabled:cursor-default ${cls}`}>
                        <span className="font-mono text-[10px] text-slate-500 mr-1.5">{'ABCD'[i]}</span>
                        {opt}
                      </button>
                    );
                  })}
                </div>
                {!done && (
                  <div className="mt-2">
                    <button onClick={() => setHintLevel((h) => ({ ...h, [ch.id]: Math.min((h[ch.id] ?? 0) + 1, ch.hints.length) }))}
                      className="min-h-9 px-3 rounded-lg bg-amber-950/60 border border-amber-800 text-[11px] font-bold text-amber-300">
                      hint {Math.min(lvl + 1, ch.hints.length)}/3
                    </button>
                    {lvl > 0 && (
                      <p className="mt-2 text-xs text-amber-200/90 bg-amber-950/30 border border-amber-900/60 rounded-lg px-3 py-2 inline-block">
                        {ch.hints[lvl - 1]}
                      </p>
                    )}
                  </div>
                )}
                {done && (
                  <div className={`mt-3 p-3 rounded-xl border text-xs leading-relaxed ${
                    picked === ch.correctIndex ? 'bg-emerald-950/30 border-emerald-800 text-emerald-200' : 'bg-rose-950/30 border-rose-800 text-rose-200'
                  }`}>
                    <span className="font-bold">{picked === ch.correctIndex ? 'Correct. ' : 'Not quite. '}</span>
                    {ch.explanation}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* ============================================================ */}
      {/* TAB 5: TRUTHS                                                */}
      {/* ============================================================ */}
      {tab === 'truths' && (
        <div className="space-y-3">
          <div className="p-4 bg-rose-950/20 rounded-2xl border border-rose-900/60">
            <p className="text-[11px] font-bold uppercase tracking-wider text-rose-400 mb-3">Misconception killer — tap to open</p>
            <div className="space-y-2">
              {MISCONCEPTIONS.map((m, i) => (
                <div key={i} className="bg-slate-900/80 rounded-xl border border-slate-800 overflow-hidden">
                  <button onClick={() => setOpenMisc(openMisc === i ? null : i)}
                    className="w-full text-left px-4 py-3 flex items-center justify-between gap-3">
                    <span className="text-xs font-bold text-rose-300">“{m.misconception}”</span>
                    <span className="text-slate-500 text-lg leading-none">{openMisc === i ? '−' : '+'}</span>
                  </button>
                  {openMisc === i && <p className="px-4 pb-3 text-xs text-slate-300 leading-relaxed">{m.correction}</p>}
                </div>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div className="p-4 bg-slate-900/70 rounded-2xl border border-slate-800">
              <p className="text-xs font-bold text-emerald-300 uppercase tracking-wider mb-2">Formula sheet (all live in this sim)</p>
              <ul className="text-xs text-slate-300 space-y-1.5 font-mono">
                <li>P(E) = favourable / total (equally likely)</li>
                <li>empirical P(E) = hits / trials</li>
                <li>0 ≤ P(E) ≤ 1 ; sum over all outcomes = 1</li>
                <li>P(not E) = 1 − P(E)</li>
                <li>two dice: 36 ordered outcomes; sums 2…12</li>
                <li>noise width ≈ 1/√N</li>
              </ul>
            </div>
            <div className="p-4 bg-slate-900/70 rounded-2xl border border-slate-800">
              <p className="text-xs font-bold text-emerald-300 uppercase tracking-wider mb-2">Honest-numerics notes</p>
              <ul className="text-xs text-slate-400 space-y-1.5 leading-relaxed">
                <li>• All randomness comes from a seeded LCG (seed shown on screen): the same seed and click sequence always rebuilds the same tally — reproducible classroom experiments.</li>
                <li>• No probability on screen is canned: every empirical value is hits/N from the actual tally; every theory value is counted from the outcome space (36 ordered pairs for two dice).</li>
                <li>• The envelope ±1/√N is a guideline band, not a guarantee — occasional escapes beyond it are themselves expected behaviour of randomness.</li>
                <li>• Class 9 keeps probability experimental; theoretical counting formally deepens in Class 10 — the two panels already agree here.</li>
              </ul>
            </div>
          </div>

          <div className="p-4 bg-slate-900/70 rounded-2xl border border-slate-800">
            <p className="text-xs font-bold text-slate-200 uppercase tracking-wider mb-2">Where this chapter goes next</p>
            <p className="text-xs text-slate-400 leading-relaxed">
              The empirical→theoretical convergence you just watched is the bridge from Class 9
              (experimental probability, statistics) to Class 10 (classical probability on cards,
              coins and dice) and onward to the frequency interpretation used by scientists polling
              voters, testing medicines, or modelling queues. Same P(E), bigger laboratory.
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

export default C9_MathsProbabilitySim;
